// ==================== 类型定义 ====================
export interface ResolutionOption {
  value: string;
  label: string;
  pixelCount?: number; // 用于排序和比较
}

export interface RatioOption {
  value: string;
  label: string;
  width: number;
  height: number;
}

export interface ResolutionResult {
  width: number;
  height: number;
  resolutionString: string;
}

export type MediaType = 'image' | 'video';
export type QualityLevel = 'standard' | 'hd' | 'ultra-hd';

