// ==================== 简化的分辨率配置系统 ====================

/**
 * 分辨率基准值配置
 */
const RESOLUTION_BASE_VALUES = {
  // 生成功能的质量等级映射
  image: {
    standard: 512,
    hd: 768,
    'ultra-hd': 1024
  },
  video: {
    standard: 720,    // 标清
    hd: 1080,         // 高清
    'ultra-hd': 1440  // 超清
  },
  // 视频分辨率规格的直接映射
  videoResolution: {
    '1080p': 1080,
    '2k': 1440,
    '4k': 2160
  }
} as const;

/**
 * 解析比例字符串为数值对象
 */
function parseRatio(ratioKey: string): { width: number; height: number } | null {
  // 从预定义选项中查找
  const allRatioOptions = [...imageAllRatioOptions, ...videoAllRatioOptions];
  const ratioOption = allRatioOptions.find(option => option.value === ratioKey);
  
  if (ratioOption) {
    return { width: ratioOption.width, height: ratioOption.height };
  }

  // 解析 "16:9" 格式
  const match = ratioKey.match(/^(\d+):(\d+)$/);
  if (match) {
    return {
      width: parseInt(match[1]),
      height: parseInt(match[2])
    };
  }

  return null;
}

/**
 * 根据清晰度和比例计算分辨率
 * @param qualityKey 清晰度等级
 * @param ratioKey 比例字符串
 * @param type 媒体类型
 * @returns 分辨率结果对象
 */
export function calculateResolution(
  qualityKey: QualityLevel, 
  ratioKey: string, 
  type: MediaType = 'video'
): ResolutionResult {
  // 获取基准值
  const baseValue = RESOLUTION_BASE_VALUES[type][qualityKey] || RESOLUTION_BASE_VALUES[type]['hd'];
  
  // 解析比例
  const ratio = parseRatio(ratioKey);
  if (!ratio) {
    // 默认返回 1920x1080
    return {
      width: 1920,
      height: 1080,
      resolutionString: '1920x1080'  // 修复：移除空格，符合接口要求
    };
  }

  // 计算实际分辨率 - 以较短边为基准
  let width: number, height: number;
  
  if (ratio.width >= ratio.height) {
    // 横向或正方形：以高度为基准
    height = baseValue;
    width = Math.round(height * ratio.width / ratio.height);
  } else {
    // 竖向：以宽度为基准
    width = baseValue;
    height = Math.round(width * ratio.height / ratio.width);
  }

  return {
    width,
    height,
    resolutionString: `${width}x${height}`  // 修复：移除空格，符合接口要求
  };
}

// ==================== 工具函数 ====================

/**
 * 获取生成功能分辨率选项的标签
 * @param value 分辨率选项值
 * @returns 对应的标签
 */
export function getResolutionLabel(value: string): string {
  const option = resolutionOptions.find(opt => opt.value === value);
  return option?.label || value;
}

/**
 * 获取视频分辨率规格选项的标签
 * @param value 视频分辨率选项值
 * @returns 对应的标签
 */
export function getVideoResolutionLabel(value: string): string {
  const option = videoResolutionOptions.find(opt => opt.value === value);
  return option?.label || value;
}

/**
 * 直接计算分辨率字符串
 * @param qualityKey 清晰度等级
 * @param ratioKey 比例字符串
 * @param type 媒体类型
 * @returns 分辨率字符串，如 "1920 x 1080"
 */
export function getResolutionString(
  qualityKey: QualityLevel, 
  ratioKey: string, 
  type: MediaType = 'video'
): string {
  return calculateResolution(qualityKey, ratioKey, type).resolutionString;
}